from pathlib import Path
import os,subprocess,json,urllib.request,urllib.parse,ssl
R=Path('/root/csi-integration');os.environ['KUBECONFIG']='/root/.kube/config'
def facts():return {str(x['vmid']):x for x in json.loads((R/'nodes-access.json').read_text())['nodes']}
def node(vmid,code):
 v=facts()[str(vmid)];guard='set -euo pipefail\ntest "$(cat /sys/class/dmi/id/product_uuid)" = "'+v['uuid']+'"\ntest "$(hostname -s)" = "'+v['name']+'"\n'
 p=subprocess.run(['ssh','-i',str(R/'id_ed25519'),'-o','IdentitiesOnly=yes','-o','BatchMode=yes','-o','StrictHostKeyChecking=yes','-o','UserKnownHostsFile='+str(R/'nodes-known_hosts'),'csi-lab@'+v['ip'],'sudo','-n','bash','-s'],input=guard+code,text=True,capture_output=True,timeout=240)
 if p.returncode:raise RuntimeError(v['name']+': '+p.stderr[-1500:])
 return p.stdout
def api(method,path,params=None,identity='terraform'):
 a=json.loads((R/'private'/f'{identity}-token.json').read_text());data=None if params is None else urllib.parse.urlencode(params).encode()
 req=urllib.request.Request('https://10.9.9.20:8006/api2/json'+path,data=data,method=method,headers={'Authorization':'PVEAPIToken='+a['token_id']+'='+a['token_secret']})
 with urllib.request.urlopen(req,context=ssl._create_unverified_context(),timeout=45) as f:return json.load(f)['data']
def k(*args,input=None):return subprocess.check_output(['kubectl',*args],input=input,text=True,timeout=240)
def j(*args):return json.loads(k(*args,'-o','json'))
def save(name,data):
 (R/'evidence').mkdir(exist_ok=True);(R/'evidence'/name).write_text(json.dumps(data,indent=2)+'\n')
def tf(args,log):
 with (R/log).open('w') as out:p=subprocess.run(['python3',str(R/'tf.py'),*args],stdout=out,stderr=subprocess.STDOUT)
 if p.returncode:print((R/log).read_text()[-2500:],flush=True);raise RuntimeError('Terraform failed: '+log)
def memory_guard():
 m=api('GET','/nodes/pve/status')['memory']['available']
 if m<2*2**30:
  for vm in api('GET','/cluster/resources?type=vm'):
   if vm.get('vmid') in [981,982,983] and vm.get('pool')=='csi-integration-20261004' and vm.get('status')=='running':api('POST',f"/nodes/pve/qemu/{vm['vmid']}/status/stop",{})
  raise RuntimeError('Host memory floor violated, stopped lab cluster VMs')
 return m

